void Bench_init(Bench *ui)
{
    if (!ui) return;
    memset(ui, 0, sizeof *ui);
    ui->tr_scale_milli = 1000;
    ui->tr_config = 0;
    ui->tr_open = 1;
    tr_copy(ui->station, sizeof ui->station, "North bench");
    ui->station_len = 11;
    tr_copy(ui->who, sizeof ui->who, "Ada");
    ui->who_len = 3;
    tr_copy(ui->secret, sizeof ui->secret, "");
    ui->secret_len = 0;
    tr_copy(ui->notes, sizeof ui->notes, "Check the gain, then arm the run.");
    ui->notes_len = 33;
    tr_copy(ui->status, sizeof ui->status, "");
    ui->status_len = 0;
    ui->armed = 0;
    ui->mode = 0;
    ui->channel = 0;
    ui->gain = 42;
    ui->passes = 0;
    ui->edits = 0;
    ui->opened = 0;
    ui->show_about = 0;
    ui->show_tip = 0;
    ui->picked = 0;
    ui->ratio = 42;
    ui->tint_r = 80;
    ui->tint_g = 140;
    ui->tint_b = 220;
    ui->page = 0;
    ui->marks = 3;
    ui->bias = 1.25;
    ui->span = 2.5;
    ui->tr_p_34_value = 40;
    ui->tr_p_41_open = 1;
    ui->tr_p_43_open = 1;
    ui->tr_p_57_a = 255;
}

void Bench_set_config(Bench *ui, const char *name)
{
    int i;
    if (!ui || !name) return;
    for (i = 0; i < 3; i++) {
        if (strcmp(tr_cfgs[i], name) == 0) ui->tr_config = i;
    }
}

